mapper.select:
SELECT COUNT(*)
FROM weekly_work_schedule
WHERE employee_id = #{employeeId}

SELECT weekly_id as weeklyId, employee_id as employeeId, start_date as startDate, end_date as endDate, approval_status as approvalStatus, plan_date as planDate, work_form as workForm, schedule_title as scheduleTitle, memo as memo, created_at as createdAt, update_at as updatedAt FROM weekly_work_schedule
approval_status = #{status}
ORDER BY start_date DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM weekly_work_schedule
WHERE employee_id = #{employeeId}
  AND approval_status IN ('PENDING', 'APPROVED')
  AND start_date <= #{endDate}
  AND end_date >= #{startDate}
